CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scan_runs (run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, completed_at TEXT, scopes_json TEXT NOT NULL, index_revision TEXT NOT NULL, capabilities_json TEXT NOT NULL, skill_count INTEGER NOT NULL, finding_count INTEGER NOT NULL, status TEXT NOT NULL, report_id TEXT);
CREATE TABLE IF NOT EXISTS skill_installations (installation_id TEXT PRIMARY KEY, skill_id TEXT NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE, target TEXT NOT NULL, root_path TEXT NOT NULL, source_hash TEXT, installed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS governance_groups (group_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES scan_runs(run_id) ON DELETE CASCADE, relation TEXT NOT NULL, similarity REAL, rule_suggestion TEXT NOT NULL, requires_semantic_review INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS group_members (group_id TEXT NOT NULL REFERENCES governance_groups(group_id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(skill_id) ON DELETE CASCADE, PRIMARY KEY (group_id, skill_id));
CREATE TABLE IF NOT EXISTS findings (finding_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL REFERENCES scan_runs(run_id) ON DELETE CASCADE, skill_id TEXT, rule_id TEXT NOT NULL, severity TEXT NOT NULL, message TEXT NOT NULL, evidence_path TEXT, remediation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (evidence_id INTEGER PRIMARY KEY AUTOINCREMENT, group_id TEXT REFERENCES governance_groups(group_id) ON DELETE CASCADE, source_skill_id TEXT NOT NULL, target_skill_id TEXT, kind TEXT NOT NULL, value TEXT NOT NULL, excerpt TEXT, excerpt_hash TEXT, sensitive INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS agent_reviews (review_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES scan_runs(run_id) ON DELETE CASCADE, agent TEXT NOT NULL, status TEXT NOT NULL, schema_version TEXT NOT NULL, full_text_shared INTEGER NOT NULL, decisions_json TEXT NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS reports (report_id TEXT PRIMARY KEY, run_id TEXT, kind TEXT NOT NULL, markdown_path TEXT NOT NULL, json_path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS installation_plans (plan_id TEXT PRIMARY KEY, source TEXT NOT NULL, source_hash TEXT NOT NULL, decision TEXT NOT NULL, targets_json TEXT NOT NULL, target_paths_json TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, approval_token_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS installed_sources (source_hash TEXT PRIMARY KEY, source TEXT NOT NULL, installed_at TEXT NOT NULL, targets_json TEXT NOT NULL);
